# Generated by the Niobium FHE Application Design AI Assistant (FHEanna).
#
# run_test.sh report, in the order the reader needs it:
#   (a) the answer: each scored patient's 10-year risk vs the published model
#   (b) encryption fidelity: decrypted risk vs the faithful twin -> PASS/FAIL
#   (c) deployment profile: per-stage time, peak server memory, boundary sizes
#
# Usage: python3 report.py <run_dir> <record> <nrec> <mode>
# Reads <run_dir>/decrypted.txt (one "risk <fraction>" line per patient),
# <run_dir>/profile.txt, <run_dir>/sizes.txt and data/test_patients.csv.

import csv
import os
import sys

# Encryption-noise tolerance from the Stage 7 twin (design/DESIGN.md):
# 0.001 percentage points, a tenth of the last digit the risk is shown to.
TOL = 1e-5

HERE = os.path.dirname(os.path.abspath(__file__))


def band(r):
    p = r * 100.0
    return "low" if p < 10.0 else ("intermediate" if p < 20.0 else "high")


def main():
    run, record, nrec, mode = sys.argv[1], int(sys.argv[2]), int(sys.argv[3]), sys.argv[4]
    with open(os.path.join(HERE, "..", "data", "test_patients.csv")) as f:
        rows = list(csv.DictReader(f))[record:record + nrec]
    with open(os.path.join(run, "decrypted.txt")) as f:
        fhe = [float(line.split()[1]) for line in f if line.startswith("risk ")]
    if len(fhe) != len(rows):
        print(f"[FAIL] decrypted {len(fhe)} results for {len(rows)} patients")
        return 1

    print("\n=== (a) Result: 10-year cardiovascular risk (Framingham 2008, BMI model) ===")
    for i, (r, x) in enumerate(zip(rows, fhe)):
        sex = "M" if r["sex"] == "male" else "F"
        desc = (f"{sex} age {r['age']} BMI {r['bmi']} BP {r['sbp']}"
                f"{' treated' if r['bp_treated'] == '1' else ''}"
                f"{' smoker' if r['smoker'] == '1' else ''}"
                f"{' diabetic' if r['diabetic'] == '1' else ''}")
        if i < 10 or len(rows) <= 12:
            print(f"  patient {record + i:4d}: {x * 100:7.3f}%  ({band(x)})"
                  f"   published model {float(r['ref_risk']) * 100:7.3f}%   [{desc}]")
        elif i == 10:
            print(f"  ... {len(rows) - 10} more")
    if record == 0:
        print(f"  patient 0 is CVrisk's published test case: CVrisk reports 16.75%,"
              f" this run {min(max(fhe[0] * 100, 1), 30):.2f}%")
    ref_err = [abs(x - float(r["ref_risk"])) for r, x in zip(rows, fhe)]
    ref_flips = sum(band(x) != r["ref_band"] for r, x in zip(rows, fhe))
    print(f"  vs the published model over {len(rows)} patient(s): worst difference"
          f" {max(ref_err) * 100:.5f} percentage points, {ref_flips} risk-band change(s)")

    print("\n=== (b) Did encryption change the answer? (decrypted vs the plaintext twin) ===")
    tw_err = [abs(x - float(r["twin_risk"])) for r, x in zip(rows, fhe)]
    tw_flips = sum(band(x) != r["twin_band"] for r, x in zip(rows, fhe))
    worst, mean = max(tw_err), sum(tw_err) / len(tw_err)
    ok = worst <= TOL and tw_flips == 0
    print(f"  worst {worst * 100:.6f} pp, mean {mean * 100:.6f} pp"
          f" (tolerance {TOL * 100:.3f} pp), risk-band changes {tw_flips}")
    if nrec > 1:
        print(f"  validation sweep: {nrec} patients scored under ONE key set to keep it fast;"
              " the deployment generates keys per patient")
    print(f"  {'PASS' if ok else 'FAIL'}")

    print(f"\n=== (c) Deployment profile ({mode}) ===")
    prof = os.path.join(run, "profile.txt")
    if os.path.exists(prof):
        stats = {}
        with open(prof) as f:
            for line in f:
                lab, wall, mib = line.split()
                stats.setdefault(lab, []).append((float(wall), float(mib)))
        for lab, v in stats.items():
            walls = [w for w, _ in v]
            tail = (f", first {walls[0]:.2f}s then mean {sum(walls[1:]) / (len(walls) - 1):.2f}s"
                    if len(walls) > 1 else "")
            print(f"  {lab:10s} {sum(walls) / len(walls):7.2f}s mean over {len(v)}{tail};"
                  f" peak RSS {max(m for _, m in v):8.1f} MiB")
    sizes = os.path.join(run, "sizes.txt")
    if os.path.exists(sizes):
        with open(sizes) as f:
            for line in f:
                name, n = line.split()
                print(f"  {name:28s} {int(n) / 1e6:8.2f} MB")
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())
